+/**
+ * Variance per item between two days (inclusive): theoretical use (what the
+ * sales sold in those days should have used), actual use (every consume
+ * movement in those days) and actual minus theoretical, 3 decimals.
+ */
+export function varianceReport(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const byItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !(m.qty > 0)) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    const sums = byItem.get(itemId) ?? { theoretical: 0, actual: 0 };
+    sums.actual += m.qty;
+    if (isSaleMovement(m)) sums.theoretical += m.qty;
+    byItem.set(itemId, sums);
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .filter((item) => byItem.has(item.id))
+    .map((item) => {
+      const theoretical = round(byItem.get(item.id).theoretical);
+      const actual = round(byItem.get(item.id).actual);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical, actual, difference: round(actual - theoretical) };
+    });
+}
