@@ -0,0 +1,62 @@
+// Sales from the till. A sale uses one portion of the dish's recipe per dish
+// sold; the stock is consumed at the time of sale with the ledger ref
+// `sale:<ticket>`. The ledger is the record of what was imported: a ticket
+// with a `sale:` movement is not imported again (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const REF = "sale:";
+
+/** The ledger ref for a till ticket. */
+export function saleRef(ticket) {
+  return `${REF}${ticket}`;
+}
+
+/** True for a movement written by a sale. */
+export function isSaleMovement(movement) {
+  return movement.type === "consume" && String(movement.ref).startsWith(REF);
+}
+
+/** The tickets that already have sale movements in the ledger. */
+export function importedTickets(store) {
+  return new Set(store.data.movements.filter(isSaleMovement).map((m) => m.ref.slice(REF.length)));
+}
+
+/**
+ * Books sale lines { row, ticket, soldAt, dish, qty } in order, skipping
+ * tickets already in the ledger. All or nothing: when an item runs out the
+ * store is left unchanged and row_not_enough_stock names the line's row.
+ * Returns { tickets, dishes } for what was booked.
+ */
+export function recordSales(store, lines) {
+  const known = importedTickets(store);
+  const todo = lines.filter((l) => !known.has(l.ticket));
+  const qtyBefore = new Map(store.data.batches.map((b) => [b, b.qty]));
+  const movementsBefore = store.data.movements.length;
+  const seqBefore = store.data.seq.movement;
+  try {
+    for (const line of todo) {
+      const recipe = getRecipe(store, line.dish.recipeId);
+      for (const need of scaled(recipe, line.qty)) {
+        if (!(need.qty > 0)) continue;
+        try {
+          consume(store, need.itemId, need.qty, { at: line.soldAt, ref: saleRef(line.ticket) });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("row_not_enough_stock", { row: line.row, ...e.params });
+          throw e;
+        }
+      }
+    }
+  } catch (e) {
+    for (const [batch, qty] of qtyBefore) batch.qty = qty;
+    store.data.movements.length = movementsBefore;
+    store.data.seq.movement = seqBefore;
+    throw e;
+  }
+  return {
+    tickets: new Set(todo.map((l) => l.ticket)).size,
+    dishes: todo.reduce((s, l) => s + l.qty, 0),
+  };
+}
